import json
import math

H = 1e-6
TOL_RES = 1e-6
TOL_INIT = 1e-12
S_SAMPLES = [-1.0, -0.5, 0.3, 1.0]
T_SAMPLES = [0.5, 1.0, -2.0]


def options():
    e = math.exp
    return {
        "1": (lambda s, t: 3 * t * (e(s) - 1),
              lambda s, t: t / 2 * (e(-s) + 1),
              lambda s, t: t * t * e(-2 * s)),
        "2": (lambda s, t: 2 * t * (e(s) - 1),
              lambda s, t: t * (2 * e(2 * s) - 1),
              lambda s, t: t * t / 2 * (1 + e(-2 * s))),
        "3": (lambda s, t: 2 * t * (e(s) - 1),
              lambda s, t: t / 2 * (e(s) + 1),
              lambda s, t: t * t * e(2 * s)),
        "4": (lambda s, t: t * (e(-s) - 1),
              lambda s, t: -2 * t * (e(-s) - 1.5),
              lambda s, t: t * t * (2 * e(-2 * s) - 1)),
    }


def partial(f, s, t, wrt_s):
    if wrt_s:
        return (f(s + H, t) - f(s - H, t)) / (2 * H)
    return (f(s, t + H) - f(s, t - H)) / (2 * H)


def charpit_residual(X, Y, U, s, t):
    """Solve u_s = p x_s + q y_s, u_t = p x_t + q y_t for p, q,
    then return |p*q - u| scaled by max(1, |u|). None if singular."""
    xs, xt = partial(X, s, t, True), partial(X, s, t, False)
    ys, yt = partial(Y, s, t, True), partial(Y, s, t, False)
    us, ut = partial(U, s, t, True), partial(U, s, t, False)
    det = xs * yt - xt * ys
    if abs(det) < 1e-9:
        return None
    p = (us * yt - ys * ut) / det
    q = (xs * ut - xt * us) / det
    u = U(s, t)
    return abs(p * q - u) / max(1.0, abs(u))


def check(X, Y, U):
    init_ok = all(
        abs(X(0.0, t)) < TOL_INIT and
        abs(Y(0.0, t) - t) < TOL_INIT and
        abs(U(0.0, t) - t * t) < TOL_INIT
        for t in T_SAMPLES
    )
    residuals = []
    for s in S_SAMPLES:
        for t in T_SAMPLES:
            r = charpit_residual(X, Y, U, s, t)
            if r is not None:
                residuals.append(r)
    max_res = max(residuals) if residuals else float("inf")
    pde_ok = len(residuals) >= 8 and max_res < TOL_RES
    return init_ok, pde_ok, len(residuals), max_res


def main():
    evidence = {}
    passing = []
    for key, (X, Y, U) in options().items():
        init_ok, pde_ok, n_valid, max_res = check(X, Y, U)
        evidence[key] = {
            "initial_condition_ok": init_ok,
            "pde_ok": pde_ok,
            "valid_points": n_valid,
            "max_scaled_residual": float("%.3e" % max_res) if max_res != float("inf") else None,
        }
        if init_ok and pde_ok:
            passing.append(key)

    if len(passing) == 1:
        print(json.dumps({
            "final_answer": passing[0],
            "evidence": evidence,
        }, separators=(",", ":")))
    else:
        print("UNSUPPORTED")


if __name__ == "__main__":
    main()
